// LUNA Follow-up filter — Fase 3 (cap, dry-run, opt-out, proposal_sent)
// Fuente: scripts/codes/followup_filter.js → se sincroniza al workflow FU

// ========== CONFIG OPS (paquete C — activación segura) ==========
// 1) Auditoría: DRY_RUN = true → no envía WhatsApp, solo lista en n8n
// 2) Solo tu lead: primero revisar la salida sin enviar mensajes
// 3) Producción controlada: DRY_RUN = false solo después de la aprobación operativa
const DRY_RUN = true;
const MAX_PER_RUN = 3;
const MAX_STALE_HOURS = 72; // nunca enviar seguimientos con más de 72h de atraso
const LUNA_SITE = 'https://luenio.com';
// ================================================================

function formatBogota(ms) {
  const d = new Date(ms);
  if (!Number.isFinite(d.getTime())) return '';
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'America/Bogota',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).formatToParts(d);
  const g = (t) => parts.find((p) => p.type === t)?.value || '';
  return g('day') + '/' + g('month') + '/' + g('year') + ' ' + g('hour') + ':' + g('minute');
}

function isFollowupSendWindow(d) {
  try {
    const fmt = new Intl.DateTimeFormat('en-US', {
      timeZone: 'America/Bogota',
      weekday: 'short',
      hour: 'numeric',
      minute: 'numeric',
      hour12: false,
    });
    const parts = fmt.formatToParts(d || new Date());
    const map = {};
    for (const p of parts) map[p.type] = p.value;
    const dayMap = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 };
    const day = dayMap[String(map.weekday || '').toLowerCase()];
    const hour = Number(map.hour === '24' ? 0 : map.hour);
    const minute = Number(map.minute || 0);
    if (![1, 2, 3, 4, 5].includes(day)) return false;
    const mins = hour * 60 + minute;
    return mins >= 8 * 60 && mins < 20 * 60;
  } catch (e) {
    return true;
  }
}

function nextFollowupWindowIso(baseMs = Date.now()) {
  const base = Number(baseMs) || Date.now();
  for (let addH = 1; addH < 24 * 6; addH++) {
    const t = new Date(base + addH * 3600 * 1000);
    if (isFollowupSendWindow(t)) return t.toISOString();
  }
  return new Date(base + 12 * 3600 * 1000).toISOString();
}

function focusFrom(j) {
  const selectedSolution = String(j.selected_solution || '').trim().toLowerCase();
  const interestedService = String(j.interested_service || '').trim().toLowerCase();
  const serviceContext = selectedSolution + ' ' + interestedService;
  const explicitPack =
    selectedSolution === 'pack_web_chatbot' ||
    interestedService === 'pack' ||
    /\bpack\b|web_catalogo.*chatbot|chatbot.*web_catalogo/i.test(serviceContext);
  const explicitChatbot =
    !explicitPack &&
    (selectedSolution === 'chatbot_whatsapp_ia' ||
      interestedService === 'chatbot' ||
      /\bchatbot\b/i.test(serviceContext));
  const explicitWeb =
    !explicitPack &&
    !explicitChatbot &&
    (selectedSolution === 'web_catalogo' ||
      interestedService === 'web' ||
      /\bweb_catalogo\b/i.test(serviceContext));
  if (explicitPack) return 'tu *pack web + chatbot*';
  if (explicitChatbot) return 'tu *chatbot de WhatsApp*';
  if (explicitWeb) return 'tu *web / catálogo*';

  const blob = [j.business_type, j.interested_service, j.selected_solution, j.project_goal, j.conversation_summary, j.notes]
    .map((x) => String(x || ''))
    .join(' ');
  if (/\bpc\b|pcs|computador|hardware|perif/i.test(blob)) return 'tu proyecto digital para venta de *PCs*';
  if (/retail|tienda|ropa|cat[aá]logo/i.test(blob)) return 'tu proyecto para *tienda / retail*';
  if (/inmobil|arriendo|apartament/i.test(blob)) return 'tu proyecto para *inmobiliaria*';
  if (/restaurant|comida|men[uú]/i.test(blob)) return 'tu proyecto de *restaurante / local*';
  if (/servicio|consultor|cl[ií]nica/i.test(blob)) return 'tu proyecto para *servicios*';
  if (/web|catalogo|catálogo|p[aá]gina/i.test(blob)) return 'tu *web / catálogo*';
  return 'tu proyecto digital con *Luenio*';
}

function isTruthy(v) {
  return String(v || '').toLowerCase() === 'true' || v === true || v === 1 || v === '1';
}

function parseWhen(v) {
  if (v === undefined || v === null || v === '') return NaN;
  if (typeof v === 'number' && Number.isFinite(v)) {
    if (v > 1e12) return v;
    if (v > 1e9) return v * 1000;
    if (v > 20000 && v < 100000) return Math.round((v - 25569) * 86400 * 1000);
  }
  const s = String(v).trim();
  const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})[ T]+(\d{1,2}):(\d{2})/);
  if (m) {
    const dd = Number(m[1]);
    const mm = Number(m[2]);
    const yyyy = Number(m[3]);
    const hh = Number(m[4]);
    const mi = Number(m[5]);
    return Date.parse(
      yyyy +
        '-' +
        String(mm).padStart(2, '0') +
        '-' +
        String(dd).padStart(2, '0') +
        'T' +
        String(hh).padStart(2, '0') +
        ':' +
        String(mi).padStart(2, '0') +
        ':00-05:00'
    );
  }
  const t = Date.parse(s);
  return Number.isFinite(t) ? t : NaN;
}

function scoreOf(j) {
  const n = Number(j.lead_score || 0);
  if (Number.isFinite(n)) return n;
  const st = String(j.lead_status || '').toLowerCase();
  if (st === 'caliente') return 80;
  if (st === 'tibio') return 50;
  return 10;
}

function auditKey(conv, kind, scheduledMs) {
  const scheduled_at = new Date(scheduledMs).toISOString();
  return { scheduled_at, dedupe_key: [conv, kind, scheduled_at].join('|') };
}

const now = Date.now();
const items = $input.all();
const due = [];
const sendWindowOpen = isFollowupSendWindow(new Date());
const inWindow = DRY_RUN || sendWindowOpen;
let staleSkipped = 0;
const isTooStale = (timestamp) => now - timestamp > MAX_STALE_HOURS * 3600 * 1000;

for (const item of items) {
  const j = item.json || {};
  const human = isTruthy(j.human_required);
  const muted = isTruthy(j.bot_muted);
  const optOut = isTruthy(j.opt_out);
  // Compatibilidad de lectura: los valores antiguos se normalizan antes de
  // aplicar las reglas; nunca se escriben de nuevo en CRM/auditoría.
  const stageRaw = String(j.pipeline_stage || '').toLowerCase();
  const stage =
    stageRaw === 'handoff_humano'
      ? 'handoff'
      : stageRaw === 'consulta_lista_para_confirmar' || stageRaw === 'recomendacion_solucion'
        ? 'propuesta'
        : stageRaw;
  const conv = String(j.conversation_id || '').trim();
  if (!conv) continue;
  if (human || muted || optOut || stage === 'handoff' || stage === 'handoff_humano') continue;
  if (/handoff|asesor humano|opt_out|no molestar/i.test(String(j.notes || ''))) continue;

  const name = String(j.name || '').trim();
  const greet = name ? 'Hola ' + name : 'Hola';
  const focus = focusFrom(j);
  const row = j.row_number || j.rowNumber || '';
  const email = String(j.email || '').trim();
  const siteShared = isTruthy(j.site_shared);
  let selectedForLead = false;
  const hasProposal =
    isTruthy(j.proposal_sent) ||
    /propuesta|proposal_sent|borrador/i.test(
      String(j.notes || '') +
        ' ' +
        String(j.conversation_summary || '') +
        ' ' +
        String(j.last_ai_response || '') +
        ' ' +
        stage
    ) ||
    stage === 'propuesta';

  // --- 2h ---
  const st2 = String(j.followup_2h_status || '').toLowerCase().trim();
  const at2 = j.followup_2h_at || '';
  const c2 = Number(j.followup_2h_count || 0) || 0;
  if (st2 === 'pending' && at2 && c2 < 1) {
    const t2 = parseWhen(at2);
    if (Number.isFinite(t2) && t2 <= now && isTooStale(t2)) staleSkipped++;
    if (Number.isFinite(t2) && t2 <= now && !isTooStale(t2) && inWindow) {
      let msg2;
      if (hasProposal) {
        msg2 =
          greet +
          '.\n\n' +
          'Te escribí con la *propuesta* de ' +
          focus +
          '.\n\n' +
          'Cuando puedas: ¿la revisamos, la *ajustamos*, o prefieres un *asesor* (persona)?';
      } else if (email.includes('@')) {
        msg2 =
          greet +
          '.\n\n' +
          'Soy *Luna* de *Luenio*.\n\n' +
          'Seguimos con ' +
          focus +
          '.\n\n' +
          '¿Te dejo o reenvío la *propuesta* por este chat?';
      } else {
        msg2 =
          greet +
          '.\n\n' +
          'Soy *Luna* de *Luenio*.\n\n' +
          '¿Seguimos con ' +
          focus +
          '?\n\n' +
          '¿Me dejas tu *correo* o prefieres ver *precios*?';
      }
      due.push({
        json: {
          ...j,
          conversation_id: conv,
          row_number: row,
          followup_kind: '2h',
          ...auditKey(conv, '2h', t2),
          followup_message: msg2,
          skip_send: DRY_RUN,
          dry_run: DRY_RUN,
          _score: scoreOf(j),
          _due_at: t2,
          followup_2h_status_next: 'sent',
          followup_2h_count_next: String(c2 + 1),
          followup_2h_at_next: '',
          followup_status_next: String(j.followup_status || 'pending'),
          followup_count_next: String(j.followup_count || 0),
          followup_at_next:
            String(j.followup_status || 'pending').toLowerCase() === 'pending'
              ? nextFollowupWindowIso(Date.now() + 24 * 3600 * 1000)
              : j.followup_at || '',
          followup_sent_at: formatBogota(Date.now()),
        },
      });
      selectedForLead = true;
    }
  }

  // --- 24h ---
  const st24 = String(j.followup_status || '').toLowerCase().trim();
  const at24 = j.followup_at || '';
  const c24 = Number(j.followup_count || 0) || 0;
  if (!selectedForLead && st24 === 'pending' && at24 && c24 < 2) {
    const t24 = parseWhen(at24);
    if (Number.isFinite(t24) && t24 <= now && isTooStale(t24)) staleSkipped++;
    if (Number.isFinite(t24) && t24 <= now && !isTooStale(t24) && inWindow) {
      let msg24;
      if (c24 === 0) {
        msg24 =
          hasProposal || email.includes('@')
            ? greet +
              '.\n\n' +
              'Soy *Luna* de *Luenio*.\n\n' +
              'Retomo ' +
              focus +
              '.\n\n' +
              '¿Quieres que preparemos la propuesta, revisar precios o hablar con un asesor?' +
              (siteShared ? '' : '\nTrabajos: ' + LUNA_SITE)
            : greet +
              '.\n\n' +
              'Soy *Luna* de *Luenio*.\n\n' +
              'Retomo ' +
              focus +
              '.\n\n' +
              '¿Te oriento con *precios* o armamos *propuesta* por este chat?';
      } else {
        // 24h #2 — cierre + opt-out explícito
        msg24 =
          greet +
          '.\n\n' +
          'Soy *Luna* de *Luenio*.\n\n' +
          'Último aviso amable sobre ' +
          focus +
          '.\n\n' +
          'Si te interesa, responde propuesta, precios o asesor.\n' +
          'Si no quieres más mensajes, escribe *no molestar* y no te escribo más.';
      }
      due.push({
        json: {
          ...j,
          conversation_id: conv,
          row_number: row,
          followup_kind: '24h',
          ...auditKey(conv, '24h', t24),
          followup_message: msg24,
          skip_send: DRY_RUN,
          dry_run: DRY_RUN,
          _score: scoreOf(j),
          _due_at: t24,
          followup_2h_status_next: String(j.followup_2h_status || ''),
          followup_2h_count_next: String(j.followup_2h_count || 0),
          followup_2h_at_next: j.followup_2h_at || '',
          followup_status_next: c24 + 1 >= 2 ? 'sent' : 'pending',
          followup_count_next: String(c24 + 1),
          followup_at_next: c24 + 1 >= 2 ? '' : nextFollowupWindowIso(),
          followup_sent_at: formatBogota(Date.now()),
        },
      });
    }
  }
}

// Priorizar calientes y más vencidos; cap por run
due.sort((a, b) => {
  const s = (b.json._score || 0) - (a.json._score || 0);
  if (s !== 0) return s;
  return (a.json._due_at || 0) - (b.json._due_at || 0);
});

const capped = due.slice(0, MAX_PER_RUN);

// Dry-run: no envía; deja traza en mensaje para ver en ejecución n8n
if (DRY_RUN) {
  for (const d of capped) {
    d.json.followup_message =
      '[DRY-RUN ' + d.json.followup_kind + '] ' + String(d.json.followup_message || '').slice(0, 400);
    d.json.skip_send = true;
  }
}

// Metadatos de corrida (un item sintético al final si no hay due — útil en logs)
if (capped.length === 0) {
  return [
    {
      json: {
        conversation_id: '',
        skip_send: true,
        dry_run: DRY_RUN,
        followup_kind: 'none',
        followup_message: '',
        _meta: true,
        _due_total: 0,
        _capped: MAX_PER_RUN,
        _in_window: sendWindowOpen,
        _window_bypassed_for_dry_run: DRY_RUN && !sendWindowOpen,
        _scanned: items.length,
        _stale_skipped: staleSkipped,
        _max_stale_hours: MAX_STALE_HOURS,
      },
    },
  ];
}

for (const d of capped) {
  d.json._due_total = due.length;
  d.json._capped = MAX_PER_RUN;
  d.json._in_window = sendWindowOpen;
  d.json._window_bypassed_for_dry_run = DRY_RUN && !sendWindowOpen;
  d.json._scanned = items.length;
  d.json._stale_skipped = staleSkipped;
  d.json._max_stale_hours = MAX_STALE_HOURS;
}

return capped;

const audits = $input.all();
const originals = $('03 Filtro | Leads con follow-up vencido').all();

// Índice por dedupe_key. Emparejar por posición era el bug: 02a devuelve una
// fila por acierto y un único item vacío cuando no acierta ninguna, así que las
// posiciones no se corresponden con los leads y los sobrantes se perdían.
const porClave = new Map();
for (const audit of audits) {
  const clave = String(audit?.json?.dedupe_key ?? '').trim();
  if (clave) porClave.set(clave, audit.json);
}

const out = [];
for (const item of originals) {
  const original = item?.json || {};
  if (original._meta === true || !String(original.conversation_id || '').trim()) continue;

  const audit = porClave.get(String(original.dedupe_key ?? '').trim()) || {};
  const status = String(audit.status || '').toLowerCase().trim();
  const isDryRun = String(original.dry_run || 'false').toLowerCase() === 'true';
  if (status === 'attempting' || status === 'sent' || (status === 'dry_run' && isDryRun)) continue;

  // pairedItem apunta al único item de 02a: nada aguas abajo necesita resolver
  // hacia atrás más allá de este nodo, porque todos los campos del lead viajan
  // ya dentro de $json.
  out.push({ json: { ...original, audit_status: status || 'new' }, pairedItem: { item: 0 } });
}
return out;

const errorText = String($json.error_message || $json.message || 'Chatwoot follow-up failed');
throw new Error('Follow-up blocked after send failure; audit marked failed: ' + errorText.slice(0, 500));
if (false) return [{ json: { blocked_after_send_failure: true } }];
